import { describe, it, expect } from "vitest";
import { migrateScriptSource, migrateSettingsText, mapStrategy, MIGRATION_VERSION } from "../src/shared/migration";
import { parseSettings, renderSettings, defaultStrategySetting } from "../src/shared/settingsYaml";

// settings.yaml as generated by the previous release (renderSettings before the rename)
const OLD_LIVE = "# yaml-language-server: $schema=./settings.schema.json\n# Wiretrick settings \u2014 edit and save; options left commented use their default.\n\nsettings:\n  # Minimum log level shown in the panel: debug | info | warn | error\n  # logLevel: info\n  # Log lines kept in the panel (100..10000)\n  # logCap: 500\n  # Interception strategy for every handler whose route doesn't set `strategy`.\n  # An unavailable strategy means the handler doesn't run (warned) \u2014 no fallback.\n  # Compatibility: https://github.com/nimatrueway/wiretrick/blob/master/docs/strategies.md#compatibility\n  #   process: + Sees everything: documents, <script src>, CSS, images, workers, the first navigation. No banner. Async handlers, any status code, URL unchanged. \u2212 Chromium only. One-time install of the local helper and trust in its local CA. Matched hosts go through a local proxy (PAC); cert-pinned / mTLS sites break. Small per-request latency; bodies are buffered for modifyResponse.\n  #   hook: + No setup, no banner, no permissions, lightest. Works in every browser. \u2212 Only the page's own fetch/XHR. Misses documents, <script src>, images, workers and requests made before the hook loads.\n  #   webrequest: + No banner, no setup. On Firefox it reaches everything, bodies included. \u2212 Not on Chrome (MV3). Chromium MV2: no modifyResponse, no async handlers, replacements are served by redirect (URL changes, status always 200) \u2014 a replaced page shows a chrome-extension:// URL. Firefox: can't change a replaced response's status.\n  #   cdp: + Sees everything with nothing to install. \u2212 Chromium only. Chrome shows a \"being debugged\" banner while attached. May miss the first navigation in a fresh tab.\n  # process | hook | webrequest | cdp\n  # default: process\n  strategy: hook\n\nparams:\n  Demo:\n    # Run this script\n    # enabled: true\n";
const OLD_DEFAULT = "# yaml-language-server: $schema=./settings.schema.json\n# Wiretrick settings \u2014 edit and save; options left commented use their default.\n\nsettings:\n  # Minimum log level shown in the panel: debug | info | warn | error\n  # logLevel: info\n  # Log lines kept in the panel (100..10000)\n  # logCap: 500\n  # Interception strategy for every handler whose route doesn't set `strategy`.\n  # An unavailable strategy means the handler doesn't run (warned) \u2014 no fallback.\n  # Compatibility: https://github.com/nimatrueway/wiretrick/blob/master/docs/strategies.md#compatibility\n  #   process: + Sees everything: documents, <script src>, CSS, images, workers, the first navigation. No banner. Async handlers, any status code, URL unchanged. \u2212 Chromium only. One-time install of the local helper and trust in its local CA. Matched hosts go through a local proxy (PAC); cert-pinned / mTLS sites break. Small per-request latency; bodies are buffered for modifyResponse.\n  #   hook: + No setup, no banner, no permissions, lightest. Works in every browser. \u2212 Only the page's own fetch/XHR. Misses documents, <script src>, images, workers and requests made before the hook loads.\n  #   webrequest: + No banner, no setup. On Firefox it reaches everything, bodies included. \u2212 Not on Chrome (MV3). Chromium MV2: no modifyResponse, no async handlers, replacements are served by redirect (URL changes, status always 200) \u2014 a replaced page shows a chrome-extension:// URL. Firefox: can't change a replaced response's status.\n  #   cdp: + Sees everything with nothing to install. \u2212 Chromium only. Chrome shows a \"being debugged\" banner while attached. May miss the first navigation in a fresh tab.\n  # process | hook | webrequest | cdp\n  # strategy: process\n";

describe("migrateScriptSource", () => {
    const old = `wt.describe("Demo");
wt.onRequest({ match: "*://a.test/*", strategy: "process", types: ["xmlhttprequest"] }, () => ({ cancel: true }));
wt.onRequest({ match: "*://b.test/*", strategy: 'cdp' }, () => ({ cancel : true }));
wt.modifyResponse({ match: "*://c.test/*", strategy: \`hook\` }, (ctx) => ctx.body);
wt.onRequest({ match: "*://d.test/*", strategy: "webrequest" }, () => {});
`;

    it("rewrites every renamed name", () => {
        const r = migrateScriptSource(old);
        expect(r.code).toBe(`wt.about("Demo");
wt.onRequest({ match: "*://a.test/*", strategy: "helper", resourceTypes: ["xmlhttprequest"] }, () => ({ block: true }));
wt.onRequest({ match: "*://b.test/*", strategy: 'debugger' }, () => ({ block : true }));
wt.onResponseBody({ match: "*://c.test/*", strategy: \`page\` }, (ctx) => ctx.body);
wt.onRequest({ match: "*://d.test/*", strategy: "webRequest" }, () => {});
`);
        expect(r.changes).toEqual([
            "wt.describe → wt.about",
            "wt.modifyResponse → wt.onResponseBody",
            'strategy "process" → "helper"',
            'strategy "cdp" → "debugger"',
            'strategy "hook" → "page"',
            'strategy "webrequest" → "webRequest"',
            "cancel: → block:",
            "types: → resourceTypes:",
        ]);
    });

    it("is idempotent", () => {
        const once = migrateScriptSource(old).code;
        expect(migrateScriptSource(once)).toEqual({ code: once, changes: [] });
    });

    it("leaves current scripts untouched", () => {
        const cur = `wt.about("x");\nwt.onRequest({ match: "*://a/*", strategy: "helper", resourceTypes: ["script"] }, () => ({ block: true }));\n`;
        expect(migrateScriptSource(cur)).toEqual({ code: cur, changes: [] });
    });

    it("only touches scripts that use wt.", () => {
        const lib = `export const opts = { types: ["a"], cancel: false, strategy: "process" };\n`;
        expect(migrateScriptSource(lib)).toEqual({ code: lib, changes: [] });
    });

    it("keeps similar identifiers", () => {
        const src = `wt.about("x");\nconst mytypes = 1; const o = { canceled: 1, subtypes: 2, describe: 3 }; obj.describe("y"); const s = { strategy: "processing" };\n`;
        expect(migrateScriptSource(src)).toEqual({ code: src, changes: [] });
    });

    it("rewrites unrelated cancel:/types: keys too (accepted risk)", () => {
        expect(migrateScriptSource(`wt.about("x"); const o = { types: 1 };`).code).toBe(`wt.about("x"); const o = { resourceTypes: 1 };`);
    });
});

describe("migrateSettingsText", () => {
    it("regenerates the old generated block with the mapped value", () => {
        const out = migrateSettingsText(OLD_LIVE);
        expect(out).toBe(renderSettings({ logLevel: "info", logCap: 500, defaultStrategy: "page" }, [
            { name: "Demo", declared: true, enabled: true, defs: {}, values: {} } as any,
        ]));
        expect(parseSettings(out).settings?.defaultStrategy).toBe("page");
    });

    it("regenerates a commented default", () => {
        const out = migrateSettingsText(OLD_DEFAULT);
        expect(out).toBe(renderSettings({ logLevel: "info", logCap: 500, defaultStrategy: defaultStrategySetting() }, []));
        expect(out).not.toMatch(/\b(process|webrequest|cdp|hook)\b/);
    });

    it("is idempotent", () => {
        for (const t of [OLD_LIVE, OLD_DEFAULT]) {
            const once = migrateSettingsText(t);
            expect(migrateSettingsText(once)).toBe(once);
        }
    });

    it("renames a hand-written key, keeping comments, quotes and CRLF", () => {
        const t = "# mine\r\nsettings:\r\n  # keep this\r\n  strategy: 'cdp' # why\r\n  logLevel: debug\r\nparams:\r\n  X:\r\n    strategy: process\r\n";
        expect(migrateSettingsText(t)).toBe(
            "# mine\r\nsettings:\r\n  # keep this\r\n  defaultStrategy: 'debugger' # why\r\n  logLevel: debug\r\nparams:\r\n  X:\r\n    strategy: process\r\n"
        );
    });

    it("renames a commented key", () => {
        expect(migrateSettingsText("settings:\n  # strategy: webrequest\n")).toBe("settings:\n  # defaultStrategy: webRequest\n");
    });

    it("leaves current settings untouched", () => {
        const cur = renderSettings({ logLevel: "warn", logCap: 900, defaultStrategy: "debugger" }, []);
        expect(migrateSettingsText(cur)).toBe(cur);
    });
});

describe("mapStrategy", () => {
    it("maps old names and passes others through", () => {
        expect(["process", "cdp", "hook", "webrequest", "helper", "x"].map(mapStrategy)).toEqual(["helper", "debugger", "page", "webRequest", "helper", "x"]);
        expect(MIGRATION_VERSION).toBeGreaterThan(0);
    });
});
